import React, { useState } from "react";
import TaskList from "./components/TaskList";
import { Line } from "react-chartjs-2";
import { Chart as ChartJS } from "chart.js/auto";

function App() {
  const [tasks, setTasks] = useState([]);
  const [taskInputs, setTaskInputs] = useState({
    1: "",
    2: "",
    3: "",
    4: "",
  });

  const addTask = (quadrant) => {
    if (!taskInputs[quadrant].trim()) return; // Prevent adding empty tasks

    const newTask = {
      id: Date.now(),
      text: taskInputs[quadrant],
      quadrant: quadrant,
      timer: 0,
      completed: false,
    };

    setTasks([...tasks, newTask]);

    // Clear the input field for the quadrant
    setTaskInputs({ ...taskInputs, [quadrant]: "" });
  };

  const deleteTask = (taskId) => {
    setTasks(tasks.filter((t) => t.id !== taskId));
  };

  const toggleTaskCompletion = (taskId) => {
    setTasks(
      tasks.map((t) =>
        t.id === taskId ? { ...t, completed: !t.completed } : t
      )
    );
  };

  const startTimer = (taskId) => {
    setTasks(
      tasks.map((t) =>
        t.id === taskId ? { ...t, timer: Date.now() } : t
      )
    );
  };

  const stopTimer = (taskId) => {
    const taskToUpdate = tasks.find((t) => t.id === taskId);
    if (taskToUpdate) {
      const duration = (Date.now() - taskToUpdate.timer) / 1000; // seconds
      setTasks(
        tasks.map((t) =>
          t.id === taskId ? { ...t, timer: duration } : t
        )
      );
    }
  };

  const chartData = {
    labels: tasks.map((t) => t.text),
    datasets: [
      {
        label: "Task Duration (seconds)",
        data: tasks.map((t) => t.timer),
        borderColor: "rgba(75, 192, 192, 1)",
        backgroundColor: "rgba(75, 192, 192, 0.2)",
        borderWidth: 1,
      },
    ],
  };

  return (
    <div className="App">
      <h1>Eisenhower Matrix</h1>

      {/* Eisenhower Matrix Table with Independent Task Inputs */}
      <table className="matrix-table">
        <tbody>
          <tr>
            <td className="quadrant">
              <h2>Important & Urgent</h2>
              <input
                type="text"
                value={taskInputs[1]}
                onChange={(e) =>
                  setTaskInputs({ ...taskInputs, 1: e.target.value })
                }
                placeholder="Enter Task"
              />
              <button onClick={() => addTask(1)}>Add Task</button>
              <TaskList
                quadrant={1}
                tasks={tasks.filter((t) => t.quadrant === 1)}
                deleteTask={deleteTask}
                toggleTaskCompletion={toggleTaskCompletion}
                startTimer={startTimer}
                stopTimer={stopTimer}
              />
            </td>
            <td className="quadrant">
              <h2>Important & Not Urgent</h2>
              <input
                type="text"
                value={taskInputs[2]}
                onChange={(e) =>
                  setTaskInputs({ ...taskInputs, 2: e.target.value })
                }
                placeholder="Enter Task"
              />
              <button onClick={() => addTask(2)}>Add Task</button>
              <TaskList
                quadrant={2}
                tasks={tasks.filter((t) => t.quadrant === 2)}
                deleteTask={deleteTask}
                toggleTaskCompletion={toggleTaskCompletion}
                startTimer={startTimer}
                stopTimer={stopTimer}
              />
            </td>
          </tr>
          <tr>
            <td className="quadrant">
              <h2>Not Important & Urgent</h2>
              <input
                type="text"
                value={taskInputs[3]}
                onChange={(e) =>
                  setTaskInputs({ ...taskInputs, 3: e.target.value })
                }
                placeholder="Enter Task"
              />
              <button onClick={() => addTask(3)}>Add Task</button>
              <TaskList
                quadrant={3}
                tasks={tasks.filter((t) => t.quadrant === 3)}
                deleteTask={deleteTask}
                toggleTaskCompletion={toggleTaskCompletion}
                startTimer={startTimer}
                stopTimer={stopTimer}
              />
            </td>
            <td className="quadrant">
              <h2>Not Important & Not Urgent</h2>
              <input
                type="text"
                value={taskInputs[4]}
                onChange={(e) =>
                  setTaskInputs({ ...taskInputs, 4: e.target.value })
                }
                placeholder="Enter Task"
              />
              <button onClick={() => addTask(4)}>Add Task</button>
              <TaskList
                quadrant={4}
                tasks={tasks.filter((t) => t.quadrant === 4)}
                deleteTask={deleteTask}
                toggleTaskCompletion={toggleTaskCompletion}
                startTimer={startTimer}
                stopTimer={stopTimer}
              />
            </td>
          </tr>
        </tbody>
      </table>

      {/* Task Duration Chart */}
      <Line data={chartData} />
    </div>
  );
}

export default App;
